        definition: 'When a function is given directly on the standard interval -pi to pi (or 0 to 2pi) with period 2pi, Euler\'s formulae apply exactly as derived, with no rescaling needed -- this is the reference case every other unit in this module measures itself against. Working on the symmetric interval -pi to pi also exposes a shortcut before any change of interval or explicit even/odd classification is introduced: splitting f(x) into its even part and odd part shows immediately which terms of the product f(x)cos(nx) or f(x)sin(nx) integrate to zero by symmetry alone, cutting the arithmetic in half without invoking a separate theorem. The cost of ignoring this shortcut is redoing a full integral from -pi to pi when half of it was already guaranteed to cancel.',
        takeaway: 'Working on the standard period-2pi interval is not just a convenience -- symmetry within that single interval already halves the coefficient work, before any half-range or even/odd machinery is formally introduced.',
