        terms: ['change of interval', 'arbitrary period 2c', 'scaling substitution', 'rescaled frequency'],
        definition: 'Euler\'s formulae as derived assume period exactly 2pi, but almost no real signal has that exact period -- a substitution z = pi*x/c stretches or compresses any interval of length 2c into length 2pi, letting the same orthogonality machinery apply after the fact. Every occurrence of nx in the original formulae becomes n*pi*x/c after inverting the substitution, and the coefficient formulas gain a factor of 1/c in place of 1/pi to account for the different interval length. The mechanism is identical to the period-2pi case; only the argument inside every sine and cosine, and the constant out front, change to track the new period. The cost of skipping this substitution is applying the period-2pi formulas directly to a differently-scaled function, which produces a series that does not actually repeat with the right period.',
        takeaway: 'Change of interval is a relabelling of the x-axis, not new mathematics -- once z = pi*x/c maps any period 2c onto period 2pi, every Euler formula and every even/odd shortcut from the standard case carries over unchanged.',
