        definition: 'Applying the change-of-interval formulas to f(x) = x on the interval (0, 4) -- a period-4 ramp, the kind of signal a linear sweep or sawtooth generator produces -- shows the rescaling machinery working end to end on a concrete case: every coefficient integral now contains n*pi*x/2 in place of nx, and the prefactor is 1/2 in place of 1/pi. The an integral happens to vanish completely for this particular ramp, leaving a pure sine series, while bn decays like 1/n -- the same slow decay signature seen in Unit 6 for a jump discontinuity, because the periodic extension of a ramp also jumps, from 4 back down to 0, at the end of every period. The practical payoff is a formula engineers actually use for sawtooth and ramp signals in power electronics and signal generators.',
        takeaway: 'A ramp\'s periodic extension always contains a hidden jump at the wrap-around point, so even though f(x)=x looks perfectly smooth on its stated interval, its Fourier series inherits the slow 1/n convergence of a discontinuous function.',
        visual: 'sawtooth-ramp-reconstruction',
