        terms: ['half-range expansion', 'odd extension', 'sine series', 'artificial periodicity'],
        definition: 'A function f(x) is often only known or only meaningful on (0, c) -- half a would-be period -- with no natural definition outside it, for instance a beam deflection or an initial temperature profile given only for positive position. To force a sine-only series, f(x) is artificially extended to (-c, 0) by reflecting it through the origin, so that f(-x) = -f(x) by construction; this manufactured odd function then has the ordinary odd-function series from Unit 12 applied to it, but only the bn formula and only the original (0, c) data are ever actually needed. The cost is that the extension is a choice made purely to get a sine series -- nothing about the physical problem required f to behave like an odd function outside its original domain, so the series faithfully reproduces f(x) only inside (0, c), diverging from any \'real\' extension of the problem outside it.',
