        terms: ['harmonic analysis', 'mean-value method', 'tabulated data', 'fundamental harmonic'],
        definition: 'Every Euler formula so far has assumed f(x) is given as an explicit algebraic expression, but real measurements -- a crank\'s angular displacement, a machine\'s vibration reading -- arrive instead as a table of values at equally spaced points, with no formula to integrate at all. Practical harmonic analysis replaces each coefficient integral with the equivalent statement that a0, an, bn are exactly twice the mean value of f(x), f(x)cos(nx), and f(x)sin(nx) respectively, taken over the tabulated points, because the mean value of a function over its full period is by definition its integral divided by the period length. This turns every Fourier coefficient into an arithmetic averaging exercise a technician can perform with a table and a calculator, with no calculus required at the point of use, though the calculus is exactly what justifies the method underneath.',
        takeaway: 'Harmonic analysis is Euler\'s formulae in disguise -- integration becomes averaging the moment the interval is divided into equally spaced tabulated points instead of a continuous formula.',
