        slides: [8, 9, 10],
        covers: [0],
        terms: ['Fourier transform F(s)', 'kernel e^{isx}', 'inversion formula', 'existence conditions'],
        definition: 'Writing the complex form of the Fourier integral theorem as f(x) = (1/2π)∫F(s)e^{-isx}ds where F(s) = ∫f(x)e^{isx}dx, the function F(s) is called the Fourier transform of f(x) and the second equation is its inversion formula. The kernel e^{isx} carries the frequency information: multiplying f(x) by it and integrating over all x measures how strongly frequency s is present in f. Unlike a Laplace transform, no one-sided restriction and no convergence factor e^{-st} is needed if f is absolutely integrable, which is both the transform\'s convenience and its limitation -- it fails outright for functions like polynomials or unit steps that do not decay.',
        takeaway: 'F(s) is not a new object invented separately from f(x); it is exactly the same function viewed through a different, frequency-indexed basis, and the inversion formula is the proof that no information is lost in the change of basis.',
