        definition: 'A rectangular pulse f(x) = 1 for |x| < 1 and 0 for |x| > 1 is the cleanest possible test case for the transform definition, because the integral is over a finite range and involves no decay estimate. Its transform, F(s) = 2 sin(s)/s, is real because the pulse is even (the sine part of the kernel integrates to zero by odd symmetry), and it is bounded but does not decay to zero fast enough to be absolutely integrable itself -- a reminder that F(s) need not inherit all the good properties of f(x). This single example is also a standard trick for evaluating definite integrals: applying the inversion formula at a convenient x converts an unknown integral into a known value of f.',
