        terms: ['Fourier sine transform Fs(s)', 'odd extension', 'half-range (0,∞)'],
        definition: 'When a function is only defined, or only physically meaningful, on (0, ∞), the complex transform\'s two-sided integral does not apply directly, so it is replaced by the sine transform Fs(s) = √(2/π)∫₀^∞ f(x) sin(sx)dx with inversion f(x) = √(2/π)∫₀^∞ Fs(s) sin(sx)ds. It behaves as if f had been extended as an odd function to the whole real line and then complex-transformed, which is why only the sine kernel survives. Physically it is the natural transform for problems where the boundary condition at x=0 fixes the value of the function itself (a Dirichlet condition, such as a rod held at zero temperature at its end), because sin(0)=0 automatically builds that condition into every term of the transform.',
        takeaway: 'Choosing sine versus cosine transform is not a matter of taste -- it is dictated by which boundary condition at x=0 you are given, value or derivative.',
