        topic: 'Fourier cosine transform',
        slides: [17, 18, 19],
        covers: [1],
        terms: ['Fourier cosine transform Fc(s)', 'even extension', 'Neumann-type boundary condition'],
        definition: 'The cosine transform Fc(s) = √(2/π)∫₀^∞ f(x) cos(sx)dx, with inversion f(x) = √(2/π)∫₀^∞ Fc(s) cos(sx)ds, is the mirror image of the sine transform: it behaves as if f had been extended as an even function to the whole line before complex-transforming, so cos(0)=1 makes it the natural match for a boundary condition that fixes the derivative of f at x=0 rather than its value. Where the sine transform builds in u(0)=0, the cosine transform builds in u\'(0)=0, which is why the choice between the two is dictated entirely by the physics of the boundary, not by any property of f itself. A useful technique unique to this transform is differentiating under the integral sign with respect to the parameter s, which converts an otherwise intractable integral into a solvable first-order ODE in s.',
        takeaway: 'Sine and cosine transforms are the two half-range projections of the same complex transform, split by the parity of the extension, and the boundary condition -- not the function -- tells you which one to use.',
