        slides: [23, 24, 25],
        covers: [2],
        terms: ['linearity', 'superposition', 'change of scale', 'time/space dilation'],
        definition: 'The linear property, F[af(x)+bg(x)] = aF(s)+bG(s), follows directly from the linearity of the integral defining the transform and means any combination of known transforms solves a combined problem without new integration. The change-of-scale property, F[f(ax)] = (1/|a|)F(s/a), captures how compressing or stretching a signal in x stretches or compresses its transform in s inversely -- squeeze a pulse in time and its spectrum spreads out in frequency, and vice versa. Both properties exist because the transform is a linear integral operator, and together they let you build the transform of a whole family of related functions from a single computed transform, which is the entire point of having a properties toolkit rather than integrating from scratch every time.',
        takeaway: 'A signal squeezed in time always spreads in frequency by the same factor -- this reciprocal scaling is the mathematical root of the time-bandwidth tradeoff that shows up everywhere in signal processing.',
        visual: 'linearity-and-scaling-panels',
        visualSpec: 'Two stacked panels. Top panel \'Linearity\': three small transform-pair icons (f1->F1, f2->F2) combining via a plus-and-scale symbol into (af1+bg2 -> aF1+bG2), drawn as a simple algebraic flow left to right. Bottom panel \'Change of scale\': a narrow tall pulse f(ax) on the left (a>1, compressed) with an arrow to a wide short curve F(s/a)/|a| on the right (spread out), and beside it a wide short pulse f(x/a) (a<1, stretched) with an arrow to a narrow tall F(as)·|a| curve, showing the inverse relationship explicitly with both directions. On reveal: top panel\'s three icons fade in left to right with the combination symbol animating last; bottom panel\'s compressed pulse draws first, narrowing with an animated squeeze, then its spread-out transform draws; then the stretched pulse draws widening, then its narrowed transform draws.',
