        definition: 'Convolving a rectangular pulse f(x)=1 for |x|<1 with itself is the single clearest geometric picture of what convolution means: at offset x, (f*f)(x) is the length of the overlap between the pulse and a copy of itself slid by x, which is a triangle that peaks at height 2 when x=0 (full overlap) and falls linearly to zero at x=±2 (no overlap at all). This example ties directly back to the transform F(s)=2sin(s)/s computed earlier for the same rectangular pulse, and the convolution theorem predicts, without any further integration, that the triangle\'s transform must be [2sin(s)/s]²=4sin²(s)/s² -- a prediction that can be checked independently against the known transform of a triangular pulse.',
        takeaway: 'Convolving a box with itself always produces a triangle, and squaring its sinc-type transform is the fastest possible route to the triangle\'s own transform, no fresh integration required.',
        visual: 'box-convolution-to-triangle',
        visualSpec: 'A three-frame filmstrip. Frame 1: two identical rectangular pulses of height 1 spanning (-1,1), one drawn solid and one drawn as a dashed copy about to slide. Frame 2: the dashed copy mid-slide at offset x=0.5, with the overlap region between them shaded, and a small running graph beneath showing the overlap area building up as a triangle shape point by point. Frame 3: the completed triangular pulse (f*f)(x), height 2 at x=0, sloping linearly to zero at x=±2. Beneath frame 3, side by side: F(s)=2sin(s)/s (the box\'s known transform) being squared into 4sin²(s)/s² (the triangle\'s transform). On reveal: frame 1 draws first; the dashed pulse slides across frame 2 in a continuous animation while the overlap shading updates live and the running triangle graph beneath draws itself in step; frame 3\'s completed triangle fades in as the slide finishes; the squaring of F(s) types in last beneath it.',
