        mistake: 'Students carry this formula over to a Fourier SINE or COSINE transform of a second derivative without adjusting for the boundary terms u(0) or u\'(0) that do NOT automatically vanish on a half-line the way they do on the whole line -- the sine-transform version of this rule, F_s[u\'\']=-s²U_s+s·u(0), keeps an extra boundary term that the infinite-transform version does not have.',
