        definition: 'Every transform studied so far assumed a continuous signal known for all x; a digital system only ever has a finite list of N samples x[0],...,x[N-1] taken at discrete times, and the discrete Fourier transform X[k]=Σₙ₌₀^{N-1} x[n]e^{-i2πkn/N} is the tool that extracts frequency content from exactly that finite list, with no integral involved at all -- just a finite weighted sum. The inverse DFT, x[n]=(1/N)Σₖ₌₀^{N-1} X[k]e^{i2πkn/N}, recovers the samples from the spectrum, and because both sums run over the same N points, the DFT is really a change of basis for an N-dimensional vector, computed by an N×N matrix multiplication in the naive case. The DFT treats the N samples as one period of a periodic signal, so indices wrap around (circular convolution and circular shifting replace their infinite-domain, linear counterparts), which is the single biggest conceptual difference from the continuous transforms of the rest of this module.',
        takeaway: 'The DFT is not an approximation to the continuous Fourier transform -- it is an exact, self-contained transform on a finite periodic sequence, and its circular (wrap-around) indexing is the price paid for that finiteness.',
