        topic: 'Fast Fourier transform (FFT): the Cooley-Tukey radix-2 algorithm',
        slides: [50, 51, 52],
        covers: [9],
        terms: ['radix-2 decimation-in-time', 'even/odd split', 'butterfly operation', 'O(N log N)'],
        definition: 'The FFT is not a different transform from the DFT -- it computes exactly the same X[k] values -- but it exploits the periodicity and symmetry of the twiddle factors to do it in O(N log N) operations instead of the DFT definition\'s O(N²). The core trick, radix-2 decimation-in-time, splits the N-point sum into two (N/2)-point DFTs, one over the even-indexed samples and one over the odd-indexed samples, then combines them using the identity X[k] = E[k] + W_N^k·O[k] and X[k+N/2] = E[k] - W_N^k·O[k], where E and O are the two half-size DFTs and W_N^k is a single twiddle factor -- this combine step is called a butterfly. Applying the same even/odd split recursively (which requires N to be a power of 2) turns one O(N²) problem into log₂N stages of O(N) combining work each, which is the single algorithmic idea that made real-time digital signal processing practical.',
        takeaway: 'The FFT is a smarter way to COMPUTE the same numbers the DFT defines, not a more accurate or different transform -- recognising this distinction (definition versus algorithm) is the most important idea in this unit.',
