          lang: 'python',
          src: 'import cmath\ndef fft(x):\n    N = len(x)\n    if N == 1:\n        return x\n    even = fft(x[0::2])\n    odd = fft(x[1::2])\n    X = [0]*N\n    for k in range(N//2):\n        t = cmath.exp(-2j*cmath.pi*k/N) * odd[k]\n        X[k] = even[k] + t\n        X[k+N//2] = even[k] - t\n    return X\n\nprint(fft([1,0,-1,0]))  # [0j, (2+0j), 0j, (2+0j)]',
