        definition: 'The Z-transform is a linear operator: for constants a, b, c and sequences u_n, v_n, w_n, Z(a*u_n + b*v_n - c*w_n) = a*Z(u_n) + b*Z(v_n) - c*Z(w_n). This follows directly from the sum defining the transform, since a sum of sums splits term by term exactly like an integral does for Laplace transforms. Linearity is what lets you transform a complicated sequence such as 3n - 4 sin(n*pi/4) + 5a by breaking it into pieces you already know from the standard table, transform each piece separately, and add the results back together.',
