        definition: 'Shifting a sequence in time corresponds to multiplying its transform by a power of z. For a right shift by k steps (delaying the sequence), Z(u_{n-k}) = z^-k U(z), a clean result because the delayed samples that would be negative-indexed are simply zero. For a left shift by k steps (advancing the sequence), Z(u_{n+k}) = z^k[U(z) - u_0 - u_1 z^-1 - ... - u_{k-1} z^-(k-1)], and the correction terms are unavoidable because advancing the sequence discards its first k known values, which must be subtracted out explicitly. This asymmetry between right and left shift is exactly why difference equations, which involve terms like u_{n+2}, always carry initial-condition correction terms when transformed.',
        takeaway: 'Right shift is a clean multiplication by z^-k because it only ever introduces zeros; left shift always costs you a correction term for every sample it throws away, which is the mechanical reason initial conditions appear when you transform a difference equation.',
