        definition: 'A linear difference equation with constant coefficients, such as u_{n+2} + 4u_{n+1} + 3u_n = 3^n with given initial conditions u_0 and u_1, can be solved by taking the Z-transform of every term using the shifting property, which converts each shifted term into a power of z times U(z) plus known correction terms built from the initial conditions. Collecting all the U(z) terms on one side turns the recurrence into a single algebraic equation for U(z), which is then solved by ordinary algebra and inverted by any of the three methods from earlier units. This four-step procedure -- transform, collect, solve, invert -- is exactly analogous to solving a linear differential equation by Laplace transforms, with the left-shift correction terms playing the role that initial conditions play there.',
