        definition: 'Operations research models are classified by what they assume about the world: a deterministic model treats every coefficient -- machine hours, unit profit, material cost -- as known exactly, while a probabilistic model admits that demand or supply times vary and must be described by distributions. Linear programming is the deterministic, continuous, linear corner of this classification: it assumes proportionality (doubling production doubles resource use), additivity (total resource use is just the sum across products, no interaction effects), and divisibility (fractional units are meaningful). These assumptions are what make the corner-point and algebraic methods in this module possible, because they guarantee the feasible region is a convex polygon or polyhedron and the optimum sits at one of its corners. The cost of the classification is that a real problem with economies of scale, uncertain demand, or indivisible units (you cannot build 2.5 machines) does not strictly satisfy linear programming\'s assumptions, and using it anyway is a deliberate approximation, not an error.',
        takeaway: 'Linear programming is not \'the\' optimization method, it is the deterministic-linear-continuous case, and every simplifying assumption behind that label is a place a real problem can quietly stop matching the model.',
