        definition: 'A linear programming problem is built from exactly three ingredients: decision variables (the quantities the decision-maker actually chooses, always required to be non-negative since negative production or negative shipment has no meaning), an objective function that is a linear combination of those variables to be maximized or minimized, and constraints that are linear inequalities or equations bounding what combinations of the variables are physically or contractually possible. A solution is any set of variable values; a feasible solution is one that also satisfies every constraint and the non-negativity restriction. The mechanism that makes LP tractable is that all three ingredients are linear -- no products of variables, no squares, no variable in a denominator -- which is precisely what keeps the set of feasible solutions a flat-sided (convex) region rather than a curved one. The cost of this restriction is that any genuinely non-linear cost or resource relationship (bulk discounts, diminishing returns) must be linearized or dropped before the problem qualifies as an LPP.',
        takeaway: 'An LPP is fully specified the moment you can name its decision variables, its one linear objective, and its list of linear constraints -- everything else in this module is just different ways of searching that specification for the best feasible point.',
