        definition: 'Formulation is the disciplined act of turning a paragraph about a business decision into the three-part LPP structure from the previous unit, and the product-mix problem is the classic template: a firm makes several products, each product consumes a fixed amount of each shared resource per unit made, each resource has a weekly or daily cap, and each product earns a fixed profit per unit. The mechanism is unit accounting -- for every resource, the total consumed is the sum, over all products, of (amount that product needs per unit) times (how many units of that product are made), and that sum cannot exceed what is available. Getting this right requires reading the word problem twice: once to extract the per-unit numbers into a small table, and once to write the sums as inequalities from that table, because doing both steps at once is where arithmetic slips happen. The payoff is that once formulated correctly, the problem is identical in structure to every other product-mix problem, so the same solving methods apply regardless of how many products or resources are involved.',
        takeaway: 'Formulation is table-building in disguise -- lay out products against resources with per-unit numbers first, and the objective and constraints write themselves as row and column sums.',
