        definition: 'For a two-variable LPP, each constraint plotted as a straight line on the x1-x2 plane splits the plane in half, and the intersection of all these half-planes (together with x1, x2 >= 0) is the feasible region or solution space -- the set of every point that satisfies every constraint at once. Because every boundary is a straight line, this region is always convex: the segment joining any two feasible points stays entirely inside the region, a property that fails for curved or notched regions. The reason this matters is the corner-point principle -- since the objective function Z = c1x1 + c2x2 is linear, its value changes at a constant rate as you move across the region, so it cannot have an interior maximum or minimum; the best value is forced onto the boundary, and among boundary points it is always found at one of the finitely many corners (vertices) where two constraint lines cross. This is why solving an LPP graphically reduces to a finite check: find the vertices, evaluate Z at each, and pick the best -- no calculus, no searching the interior.',
        takeaway: 'The reason LP is solvable at all -- graphically or by simplex -- is that linearity forces the optimum onto a corner of a convex region, replacing an infinite search over the plane with a finite list of points to check.',
        visual: 'convex-region-vertex-scan',
        visualSpec: 'A shaded convex polygon labelled OABC sitting in the first quadrant of an x1-x2 axis pair, bounded below and left by the axes and on the upper-right by two crossing constraint lines. Each vertex O, A, B, C is marked with a dot and a small callout box showing its (x1, x2) coordinates. A dashed \'iso-profit line\' Z=0 through the origin is shown, with a ghost trail of parallel copies of increasing Z sliding outward until the last one just touches vertex B before leaving the region entirely. On reveal: the two axes and two constraint lines draw first; the shaded convex region fills in; the four vertices pop in one at a time with their coordinate callouts; then the dashed Z=0 line appears at the origin and animates sliding outward through progressively higher parallel copies, stopping and highlighting the moment it touches its last vertex.',
