        definition: 'This unit closes the loop on the two-variable product-mix problem formulated earlier by carrying it all the way to a numeric answer using the graphical method: plot the two resource constraints, find where they cross, evaluate profit at every corner, and read off the best combination of products. The one new mechanical skill needed beyond the previous unit is solving two constraint equations simultaneously to get the exact coordinates of the corner where they intersect -- unlike the earlier example where vertices were given, here they must be computed. This matters because the intersection of two binding constraints is rarely a whole number, and rounding early introduces error that compounds through the profit calculation. The method\'s payoff is concrete: it converts an abstract \'maximize profit\' instruction into an exact weekly production plan the factory can actually schedule.',
