          'For each = constraint, leave it as is (no slack or surplus needed)',
          'If the right-hand side of any constraint is negative, multiply that whole constraint by -1 first so the right-hand side becomes non-negative',
          'For any variable unrestricted in sign, replace it everywhere with the difference of two new non-negative variables',
