          'If every Cj - Zj <= 0, stop -- the current solution is optimal',
          'Otherwise pick the entering variable as the column with the largest positive Cj - Zj (key column)',
          'Pick the leaving variable using the minimum positive ratio of b to the key column\'s entries (key row); the entry there is the key element',
          'Divide the key row by the key element, then use row operations to zero out every other entry in the key column, producing the next tableau; repeat',
