        definition: 'The simplex algorithm as built in the previous two units is stated for maximization with non-negative right-hand sides, so a minimization problem needs a one-line translation before the tableau method applies at all: minimizing Z is exactly equivalent to maximizing Z\' = -Z, since whatever makes Z as small as possible makes its negative as large as possible. Separately, if any constraint\'s right-hand side comes out negative once written as a <=, that whole constraint must be multiplied through by -1 (which flips the inequality direction) before slack and surplus variables are introduced, because the ratio test and feasibility checks in simplex assume non-negative b values throughout. Both of these are bookkeeping steps done once, up front, in Step 1 of the working procedure -- after that, every tableau, pivot, and optimality check runs exactly as in a maximization problem, and only the final answer needs to be translated back by negating Z\' to recover the true minimum Z.',
