        definition: 'The simplex algorithm\'s very first tableau needs an immediately obvious basic feasible solution, and for a pure <= problem this is free: set every decision variable to zero and let the slack variables equal the right-hand sides, which are automatically non-negative. This trick breaks down the moment a constraint is an equality or a >= inequality, because setting decision variables to zero either leaves no slack variable to be basic at all (for an equality) or forces the surplus variable to a negative value (for a >=, since a surplus is subtracted, not added). Neither of these gives a usable non-negative starting basic variable, so a new bookkeeping device, the artificial variable, is added to the left-hand side of exactly these problem constraints purely to manufacture a legitimate starting basis; its cost is then penalized so heavily in the objective function that the algorithm is driven to push it back to zero as fast as possible. The mechanism only serves as scaffolding -- an artificial variable never represents a real resource or requirement, and a final solution in which one remains positive means the original problem\'s constraints could not all be satisfied at once.',
        takeaway: 'Artificial variables exist for exactly one reason -- to hand the simplex algorithm a legal, non-negative starting point when an equality or >= constraint refuses to supply one on its own -- and they must be driven out of the basis before the final answer means anything.',
