        definition: 'A feasible solution to a transportation problem is a basic feasible solution only if it uses at most m+n-1 strictly positive allocations, one less than the total number of rim constraints, because the m row-sum and n column-sum equations are not all independent: any one of them is implied by the rest. If the number of positive allocations equals exactly m+n-1, the solution is non-degenerate; if it is fewer, the solution has degenerated and needs a tiny artificial allocation before it can be tested for optimality. An optimal solution is simply the feasible solution, among all feasible solutions, with the least total transportation cost. This m+n-1 count is not a technicality — it is exactly the number of allocations MODI needs to solve for its u_i and v_j values uniquely in the next stage.',
