        definition: 'The North-West Corner method builds a starting feasible solution by always allocating to the top-left (north-west) cell of whatever rows and columns remain, completely ignoring the cost entries. At each step it ships the maximum possible amount into that cell, min(remaining supply, remaining demand), then crosses off whichever of the row or column is now exhausted and moves one step right or down. It repeats until every supply and every demand is used up, tracing a staircase path across the table from the top-left corner to the bottom-right corner. Because it never consults cost, it is the fastest method to execute by hand but typically gives the worst starting cost of the three initial methods. Its only real job is to guarantee a feasible, non-degenerate starting point cheaply, leaving the actual cost-cutting to the optimality test that follows.',
