        definition: 'The Least Cost method builds a starting feasible solution by repeatedly finding the single cheapest remaining cell in the whole table and allocating the maximum possible amount there, min(remaining supply, remaining demand), then crossing off whichever row or column is exhausted. Unlike North-West Corner, it does use the cost numbers, which is why it usually produces a cheaper starting solution on the same table. It is still greedy and short-sighted, though: it never considers that grabbing a cheap cell now might force an expensive allocation later once rows or columns are crossed off. Ties between equally cheap cells are broken arbitrarily, typically by preferring the cell that allows the larger allocation or the lowest row index, and the convention must be stated up front so the worked answer is reproducible.',
