        terms: ['Vogel\'s approximation method', 'penalty', 'opportunity cost', 'row/column difference'],
        definition: 'Vogel\'s Approximation Method (VAM) improves on Least Cost by asking, for every row and column, not just \'what is the cheapest cell here\' but \'what do I lose if I miss the cheapest cell here and am forced into the next-cheapest one instead.\' That loss, the difference between the smallest and second-smallest cost in a row or column, is its penalty, and VAM always services the row or column with the largest penalty first, because that is where a bad decision would hurt the most. Within that chosen row or column, it still allocates to the cheapest cell, exactly like Least Cost. This one extra layer of foresight, recomputing penalties after every allocation, is why the textbook confines its full worked treatment to VAM alone among the three initial methods: it consistently yields a starting solution at least as good as, and often better than, either of the other two.',
        takeaway: 'VAM\'s insight is that the cost of a cheap cell is not what makes a row urgent, it is how expensive the row\'s second-best option would be if that cheap cell were missed.',
