        definition: 'Every initial method in this module gives a feasible starting solution, but none of them proves that solution is the cheapest possible; that proof is MODI\'s job. MODI assigns one number u_i to every row and one number v_j to every column such that, for every currently occupied (basic) cell, u_i + v_j = c_ij exactly; since there are m+n-1 occupied cells and m+n unknowns, one u or v is set to zero by convention and the rest follow by substitution. Once every u_i and v_j is known, MODI computes a net evaluation w_ij = u_i + v_j - c_ij for every empty cell: this number is the change in total cost per unit shipped if that empty cell were brought into the solution. If every w_ij is zero or negative, no empty cell can improve the plan, so the current solution is optimal; any positive w_ij means the plan can still be cheapened.',
        takeaway: 'MODI turns \'is this the cheapest plan?\' from a guess into m+n numbers and one comparison per empty cell, which is exactly why it replaces re-running simplex from scratch.',
