        topic: 'Degeneracy in transportation problems and the epsilon fix',
        slides: [34, 35, 36],
        covers: [4],
        terms: ['degeneracy', 'epsilon allocation', 'independent cell', 'loop-free placement'],
        definition: 'A transportation solution degenerates when an initial-allocation method produces fewer than m+n-1 strictly positive cells, which happens whenever a single allocation exhausts a row and a column simultaneously, collapsing what should have been two separate steps into one. A degenerate solution cannot be fed into MODI as-is, because the u_i, v_j substitution chain needs exactly m+n-1 occupied cells to solve uniquely; with fewer, some u or v is left undetermined. The standard repair is to place an infinitesimally small positive quantity, epsilon, into an otherwise-empty cell chosen so that it does not close a loop with the existing occupied cells, restoring the count to m+n-1. MODI then proceeds normally, treating the epsilon cell as occupied, and epsilon is finally allowed to shrink to zero once the optimal solution is found, without changing the reported cost.',
        takeaway: 'Degeneracy is not a dead end; it means one allocation did double duty, and a single well-placed epsilon in a loop-free cell restores exactly the bookkeeping MODI needs.',
        visual: 'degeneracy-epsilon-cell',
        visualSpec: 'A small 2-row by 3-column grid (2 origins, 3 destinations) with three filled cells shown as solid dots and one additional cell outlined and marked with the Greek letter epsilon in a faint dashed circle. A counter box reads \'positive allocations: 3\' then updates to \'with epsilon: 4 = m+n-1\'. A crossed-out loop icon next to two candidate cells shows one would create a loop (rejected, red X) while the epsilon cell chosen forms no loop (accepted, green check). On reveal: the three solid allocations appear first with the counter reading 3 and flashing red as degenerate, then the two candidate epsilon cells appear, the loop-forming one is X\'d out, and the loop-free one is accepted with epsilon written in and the counter turning green at 4.',
