        terms: ['closed loop', 'theta reallocation', 'entering cell', 'leaving cell', 'iteration'],
        definition: 'When MODI finds a positive net evaluation at some empty cell, that cell must enter the solution, and a closed loop of horizontal and vertical steps through existing occupied cells shows exactly how flow should shift to bring it in. Starting at the entering cell with a plus sign, the loop alternates plus and minus signs at each corner it turns through, always landing back on occupied cells, until it closes. The largest quantity, theta, that can be shifted without making any minus-marked cell negative is the smallest allocation currently sitting at a minus corner; adding theta to every plus corner and subtracting it from every minus corner produces the next, cheaper solution. This is the exact mechanism that took North-West Corner\'s 650-cost plan, corrected by one such loop, down to the same 550 that VAM reached directly.',
        takeaway: 'One positive net evaluation and one closed loop is all it takes to move from a merely feasible plan to a cheaper one; repeat until every net evaluation is non-positive.',
        visual: 'modi-loop-reallocation',
